using NUnit.Framework;

[TestFixture]
public class CountDigitsTests
{
    [TestCase("Anna123", 3)]
    [TestCase("abc", 0)]
    [TestCase("2025", 4)]
    public void Counts_Digits_Correctly(string text, int expected)
    {
        Assert.That(CountDigits(text), Is.EqualTo(expected));
    }

    private int CountDigits(string text)
    {
        int count = 0;
        foreach (var ch in text)
        {
            if (char.IsDigit(ch))
                count++;
        }
        return count;
    }
}
